# ============================================================
# FUTURE OUTCOME
# ============================================================

def get_future_outcome(
    candles,
    index,
    horizon
):

    future_index = (
        index + horizon
    )

    if (
        index < 0
        or index >= len(candles)
    ):

        return None

    if future_index >= len(candles):

        return None

    current_close = candles[
        index
    ]["close"]

    future_close = candles[
        future_index
    ]["close"]

    if future_close > current_close:

        return "UP"

    if future_close < current_close:

        return "DOWN"

    return "NEUTRAL"


# ============================================================
# OUTCOME SUMMARY
# ============================================================

def summarize_outcomes(
    outcomes
):

    total = len(outcomes)

    if total == 0:

        return {
            "total": 0,
            "up": 0,
            "down": 0,
            "neutral": 0,
            "up_rate": 0.0,
            "down_rate": 0.0,
            "neutral_rate": 0.0,
        }

    up = outcomes.count(
        "UP"
    )

    down = outcomes.count(
        "DOWN"
    )

    neutral = outcomes.count(
        "NEUTRAL"
    )

    return {

        "total": total,

        "up": up,

        "down": down,

        "neutral": neutral,

        "up_rate":
            up / total,

        "down_rate":
            down / total,

        "neutral_rate":
            neutral / total,

    }


# ============================================================
# SWING CONFIRMATION INDEX
# ============================================================

def get_swing_signal_index(
    swing
):

    # --------------------------------------------------------
    # Prefer an explicitly stored confirmation index.
    # --------------------------------------------------------

    for key in (
        "confirmation_index",
        "confirmed_index",
        "confirm_index",
    ):

        value = swing.get(
            key
        )

        if isinstance(
            value,
            int
        ):

            return value


    # --------------------------------------------------------
    # Otherwise reconstruct confirmation index from the
    # exact SWING_LOOKBACK used by v3.5.1.
    # --------------------------------------------------------

    swing_index = swing.get(
        "index"
    )

    if swing_index is None:

        return None


    if SWING_LOOKBACK is None:

        raise RuntimeError(
            "SWING_LOOKBACK is not exposed by "
            "v3.5.1 and swing confirmation index "
            "is not stored in the swing record."
        )


    return (
        swing_index
        + SWING_LOOKBACK
    )


