# ============================================================
# GROUP TEST
# ============================================================

def run_group_test(
    title,
    signal_types,
    expected_direction
):

    print()
    print("=" * 80)
    print(title)
    print("=" * 80)


    for horizon in STRUCTURE_TEST_HORIZONS:

        outcomes = []


        for signal_type in signal_types:

            for signal in structure_signals.get(
                signal_type,
                []
            ):

                outcome = get_future_outcome(
                    normalized_candles,
                    signal["index"],
                    horizon
                )


                if outcome is not None:

                    outcomes.append(
                        outcome
                    )


        summary = summarize_outcomes(
            outcomes
        )


        directional_total = (
            summary["up"]
            + summary["down"]
        )


        if directional_total > 0:

            if expected_direction == "UP":

                expected_accuracy = (
                    summary["up"]
                    / directional_total
                )

            else:

                expected_accuracy = (
                    summary["down"]
                    / directional_total
                )

        else:

            expected_accuracy = None


        baseline = global_baselines[
            horizon
        ]


        baseline_directional_total = (
            baseline["up"]
            + baseline["down"]
        )


        if baseline_directional_total > 0:

            baseline_accuracy = (
                max(
                    baseline["up"],
                    baseline["down"]
                )
                / baseline_directional_total
            )

        else:

            baseline_accuracy = None


        print()
        print(
            f"Horizon {horizon}"
        )

        print(
            f"Observations: "
            f"{summary['total']}"
        )

        print(
            f"Future UP: "
            f"{summary['up_rate']:.2%}"
        )

        print(
            f"Future DOWN: "
            f"{summary['down_rate']:.2%}"
        )

        print(
            f"Future NEUTRAL: "
            f"{summary['neutral_rate']:.2%}"
        )


        if expected_accuracy is not None:

            print(
                f"Expected-direction accuracy: "
                f"{expected_accuracy:.2%}"
            )


        if baseline_accuracy is not None:

            print(
                f"Baseline: "
                f"{baseline_accuracy:.2%}"
            )


        if (
            expected_accuracy is not None
            and baseline_accuracy is not None
        ):

            print(
                f"Difference vs baseline: "
                f"{expected_accuracy - baseline_accuracy:+.2%}"
            )


